// The setup conversation (spec 0003 R0-R0f): one question at a time,
// resumable (ADR 0038 -- every bit of state below is a row, nothing
// carried between messages any other way), and structural writes always
// run as the asking member's own role (ADR 0042's "acts_as") so a
// non-admin's attempt fails at the database (R0c, A4), never in this
// workflow's own logic.
const crypto = require('crypto');
const http = require('http');
const fs = require('fs');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintToken(role, memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role, member_id: memberId, exp: Math.floor(Date.now() / 1000) + 60 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

async function main() {
  const item = $input.first().json;
  const { member_id, chat_id, message_thread_id, text, language_hint } = item;
  const isRu = language_hint === 'ru';

  const readToken = mintToken('hh_agent', member_id);
  const readAuth = { Authorization: `Bearer ${readToken}` };

  const memberRes = await httpJson('GET', `${PG}/member?id=eq.${member_id}&select=role`, readAuth);
  const role = (memberRes.body && memberRes.body[0] && memberRes.body[0].role) === 'admin' ? 'hh_admin' : 'hh_member';
  const actingToken = mintToken(role, member_id);
  const auth = { Authorization: `Bearer ${actingToken}` };

  const QUESTIONS = {
    accounts: isRu
      ? 'Какой у вас первый счёт? Название, что это (счёт, карта, кредит) и сколько на нём сейчас — или напишите "готово", если счетов больше нет.'
      : "What's the first account? Its name, what kind it is (bank account, card, loan), and what it holds today -- or say \"done\" if that's all of them.",
    household_settings: isRu ? 'В каком часовом поясе и в какой валюте вы живёте?' : 'What timezone and currency does the household use?',
    default_payment_account: isRu ? 'Какой счёт использовать по умолчанию для ваших трат?' : 'Which account should be your own default for spending?',
  };

  const STATUS_TRIGGER = /what.*(left|remain)|что.*(осталось|осталась)/i;

  const openRes = await httpJson('GET', `${PG}/conversation?member_id=eq.${member_id}&kind=eq.setup&closed_at=is.null`, auth);
  let conversation = (openRes.body || [])[0] || null;

  if (!conversation) {
    const created = await httpJson('POST', `${PG}/conversation`, Object.assign({ Prefer: 'return=representation' }, auth), {
      member_id, kind: 'setup', step: 'accounts', payload: {},
    });
    if (created.status < 200 || created.status >= 300) {
      const refusal = isRu ? 'Только администратор может настраивать счета.' : 'Only an admin can set up the accounts.';
      return [{ json: { chat_id, message_thread_id, text: refusal } }];
    }
    conversation = created.body[0];
    return [{ json: { chat_id, message_thread_id, text: QUESTIONS.accounts } }];
  }

  if (STATUS_TRIGGER.test(text)) {
    const order = ['accounts', 'household_settings', 'default_payment_account'];
    const remaining = order.slice(order.indexOf(conversation.step)).map((s) => QUESTIONS[s]);
    const header = isRu ? 'Осталось:' : 'Still remaining:';
    return [{ json: { chat_id, message_thread_id, text: `${header}\n${remaining.join('\n')}` } }];
  }

  const systemPrompt = fs.readFileSync('/prompts/setup-conversation/v1/system.md', 'utf8');
  const modelName = $env.MODEL_TEXT_EXTRACTION ? $env.MODEL_TEXT_EXTRACTION.replace('capture-text', 'setup-conversation') : 'meowhub/setup-conversation-stub';

  let context = { step: conversation.step };
  if (conversation.step === 'default_payment_account') {
    const accountsRes = await httpJson('GET', `${PG}/account?active=eq.true&select=name`, auth);
    context.known_accounts = (accountsRes.body || []).map((a) => a.name);
  }

  let modelRes;
  try {
    modelRes = await httpJson('POST', `${$env.OPENROUTER_BASE_URL}/chat/completions`, {}, {
      model: modelName,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: JSON.stringify({ text, context }) },
      ],
    });
  } catch (e) {
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не получилось обработать это сейчас.' : "Couldn't process that right now." } }];
  }

  let parsed = null;
  try {
    const candidate = JSON.parse(modelRes.body.choices[0].message.content);
    parsed = (candidate && (candidate.status === 'resolved' || candidate.status === 'question')) ? candidate : null;
  } catch (e) {
    parsed = null;
  }

  if (!parsed || parsed.status === 'question') {
    const question = (parsed && parsed.question) || (isRu ? 'Не могу разобрать — повторите, пожалуйста?' : "I couldn't make sense of that -- could you say it again?");
    return [{ json: { chat_id, message_thread_id, text: question } }];
  }

  async function advanceTo(step) {
    await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { step, last_touched_at: new Date().toISOString() });
  }

  if (conversation.step === 'accounts') {
    if (parsed.done) {
      await advanceTo('household_settings');
      return [{ json: { chat_id, message_thread_id, text: QUESTIONS.household_settings } }];
    }
    const accRes = await httpJson('POST', `${PG}/account`, Object.assign({ Prefer: 'return=representation' }, auth), {
      type: parsed.account_type, name: parsed.account_name,
    });
    if (accRes.status < 200 || accRes.status >= 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Только администратор может добавлять счета.' : 'Only an admin can add accounts.' } }];
    }
    const accountId = accRes.body[0].id;
    if (parsed.overdraft_limit_minor || parsed.credit_limit_minor) {
      await httpJson('POST', `${PG}/account_term`, Object.assign({ Prefer: 'return=minimal' }, auth), {
        account_id: accountId, overdraft_limit: parsed.overdraft_limit_minor, credit_limit: parsed.credit_limit_minor, effective_from: new Date().toISOString().slice(0, 10),
      });
    }
    // Opening balance (R3): its own transaction against Equity, confirmed
    // on creation (ADR 0023 -- nothing for a human to second-guess in a
    // number the household just stated).
    let equityRes = await httpJson('GET', `${PG}/account?type=eq.equity&name=eq.Opening%20Balances`, auth);
    let equityId;
    if ((equityRes.body || []).length) {
      equityId = equityRes.body[0].id;
    } else {
      const createdEquity = await httpJson('POST', `${PG}/account`, Object.assign({ Prefer: 'return=representation' }, auth), { type: 'equity', name: 'Opening Balances' });
      equityId = createdEquity.body[0].id;
    }
    const balance = parsed.opening_balance_minor || 0;
    const signedForAccount = parsed.account_type === 'liability' ? -balance : balance;
    // R13: no member writes a raw posting under any role -- an opening
    // balance is the agent composing a transaction from what the admin
    // just stated, the same shape as any other capture (ADR 0042), not
    // a structural change like the account it posts against.
    const composeToken = mintToken('hh_agent', member_id);
    const composeAuth = { Authorization: `Bearer ${composeToken}` };
    const txnRes = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, composeAuth), {
      date: new Date().toISOString().slice(0, 10), submitter: member_id, source: 'manual',
      confirmation_state: 'confirmed', confirmation_route: 'review', confirmed_by: member_id, confirmed_at: new Date().toISOString(),
    });
    const txnId = txnRes.body[0].id;
    await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, composeAuth), [
      { transaction_id: txnId, account_id: accountId, amount: signedForAccount, currency: 'EUR' },
      { transaction_id: txnId, account_id: equityId, amount: -signedForAccount, currency: 'EUR' },
    ]);
    const confirmMsg = isRu
      ? `Добавил «${parsed.account_name}». Ещё счета? Или напишите "готово".`
      : `Added "${parsed.account_name}". Another account, or say "done"?`;
    return [{ json: { chat_id, message_thread_id, text: confirmMsg } }];
  }

  if (conversation.step === 'household_settings') {
    if (parsed.timezone) {
      await httpJson('POST', `${PG}/household_setting`, Object.assign({ Prefer: 'resolution=merge-duplicates' }, auth), { key: 'timezone', value: parsed.timezone, updated_by: member_id });
    }
    if (parsed.currency) {
      await httpJson('POST', `${PG}/household_setting`, Object.assign({ Prefer: 'resolution=merge-duplicates' }, auth), { key: 'default_currency', value: parsed.currency, updated_by: member_id });
    }
    await advanceTo('default_payment_account');
    return [{ json: { chat_id, message_thread_id, text: QUESTIONS.default_payment_account } }];
  }

  if (conversation.step === 'default_payment_account') {
    const accLookup = await httpJson('GET', `${PG}/account?name=eq.${encodeURIComponent(parsed.account_name)}&select=id`, auth);
    if (!(accLookup.body || []).length) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл такой счёт — как он называется?' : "I couldn't find that account -- what's it called?" } }];
    }
    const defaultAccountId = accLookup.body[0].id;
    await httpJson('PATCH', `${PG}/member?id=eq.${member_id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { default_payment_account_id: defaultAccountId });
    await httpJson('PATCH', `${PG}/conversation?id=eq.${conversation.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { closed_at: new Date().toISOString() });
    const done = isRu ? 'Готово! Можно записывать траты.' : "All set! You're ready to capture expenses.";
    return [{ json: { chat_id, message_thread_id, text: done } }];
  }

  return [{ json: { chat_id, message_thread_id, text: isRu ? 'Что-то пошло не так.' : 'Something went wrong.' } }];
}

return main();
